291	@@ -0,0 +1,336 @@
292	+/**
293	+ * T7 — Feature-origin task tab navigation and tab flicker hardening
294	+ *
295	+ * Verifies:
296	+ *   - FeatureTasksPanel calls onOpenTaskTab with taskId, taskName, title
297	+ *   - FeatureTabView opens task tabs via workspace openTaskTab with
298	+ *     parentFeatureTabSessionId
299	+ *   - closeTaskTab reactivates parent feature tab when
300	+ *     parentFeatureTabSessionId is set
301	+ *   - closeTaskTab returns to /board when no parent feature tab context
302	+ *   - Parent feature tab remains open after feature-origin task tab closes
303	+ *   - TaskTabView Back behavior preserves board-origin behavior
304	+ *   - TaskTabEntry includes parentFeatureTabSessionId
305	+ *   - Flicker hardening: loading stays false when cached data exists
306	+ */
307	+
308	+// @vitest-environment jsdom
309	+
310	+import React from "react";
311	+import { renderHook, act } from "@testing-library/react";
312	+import { renderToStaticMarkup } from "react-dom/server";
313	+import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
314	+import { beforeEach, describe, expect, it, vi } from "vitest";
315	+import { useRouter } from "next/navigation";
316	+import type { TaskDetail, FeatureDetail, TaskSummary } from "../services/workflow-backend/types";
317	+
318	+// ─── Mock next/navigation ─────────────────────────────────────────────────────
319	+
320	+vi.mock("next/navigation", () => ({
321	+  useRouter: vi.fn(),
322	+}));
323	+
324	+const mockRouterPush = vi.fn();
325	+
326	+// ─── Helper: create a TaskTabEntry for context tests ──────────────────────────
327	+
328	+import type { TaskTabEntry, WorkspaceContextValue } from "../features/workspaces/context/WorkspaceContext";
329	+import { addTaskTab, removeTaskTab, getTaskTabHref, createTabSessionId } from "../features/workspaces/lib/tabState";
330	+
331	+// ─── Test: tabState helpers ───────────────────────────────────────────────────
332	+
333	+describe("tabState — parentFeatureTabSessionId support", () => {
334	+  it("creates a TaskTabEntry with parentFeatureTabSessionId", () => {
335	+    const entry: TaskTabEntry = {
336	+      sessionId: "task-abc-123",
337	+      workspaceId: "ws-1",
338	+      taskId: "task-uuid-1",
339	+      taskName: "T1",
340	+      title: "My Task",
341	+      featureId: "feat-uuid-1",
342	+      featureName: "my-feature",
343	+      parentFeatureTabSessionId: "feat-xyz-456",
344	+    };
345	+    expect(entry.parentFeatureTabSessionId).toBe("feat-xyz-456");
346	+  });
347	+
348	+  it("addTaskTab preserves parentFeatureTabSessionId", () => {
349	+    const entry: TaskTabEntry = {
350	+      sessionId: "task-abc-123",
351	+      workspaceId: "ws-1",
352	+      taskId: "task-uuid-1",
353	+      taskName: "T1",
354	+      title: "My Task",
355	+      parentFeatureTabSessionId: "feat-xyz-456",
356	+    };
357	+    const tabs = addTaskTab([], entry);
358	+    expect(tabs).toHaveLength(1);
359	+    expect(tabs[0]?.parentFeatureTabSessionId).toBe("feat-xyz-456");
360	+  });
361	+
362	+  it("getTaskTabHref works with parentFeatureTabSessionId", () => {
363	+    const entry: TaskTabEntry = {
364	+      sessionId: "task-abc-123",
365	+      workspaceId: "ws-1",
366	+      taskId: "task-uuid-1",
367	+      taskName: "T1",
368	+      title: "My Task",
369	+      parentFeatureTabSessionId: "feat-xyz-456",
370	+    };
371	+    const href = getTaskTabHref(entry);
372	+    expect(href).toContain("/task/task-abc-123");
373	+    expect(href).toContain("workspaceId=ws-1");
374	+    expect(href).toContain("taskId=task-uuid-1");
375	+  });
376	+});
377	+
378	+// ─── Test: closeTaskTab behavior with parentFeatureTabSessionId ───────────────
379	+
380	+describe("WorkspaceContext — closeTaskTab with parentFeatureTabSessionId", () => {
381	+  beforeEach(() => {
382	+    vi.clearAllMocks();
383	+    mockRouterPush.mockReset();
384	+    (useRouter as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
385	+      push: mockRouterPush,
386	+    });
387	+  });
388	+
389	+  it("closeTaskTab removes the task tab entry from the list", () => {
390	+    const tabs: TaskTabEntry[] = [
391	+      {
392	+        sessionId: "task-abc",
393	+        workspaceId: "ws-1",
394	+        taskId: "task-1",
395	+        taskName: "T1",
396	+        title: "Task 1",
397	+        parentFeatureTabSessionId: "feat-xyz",
398	+      },
399	+      {
400	+        sessionId: "task-def",
401	+        workspaceId: "ws-1",
402	+        taskId: "task-2",
403	+        taskName: "T2",
404	+        title: "Task 2",
405	+      },
406	+    ];
407	+    const result = removeTaskTab(tabs, "task-abc");
408	+    expect(result).toHaveLength(1);
409	+    expect(result[0]?.sessionId).toBe("task-def");
410	+  });
411	+
412	+  it("task tab with parentFeatureTabSessionId is removed while unrelated tabs stay", () => {
413	+    const tabs: TaskTabEntry[] = [
414	+      {
415	+        sessionId: "task-abc",
416	+        workspaceId: "ws-1",
417	+        taskId: "task-1",
418	+        taskName: "T1",
419	+        title: "Task 1",
420	+        parentFeatureTabSessionId: "feat-xyz",
421	+      },
422	+      {
423	+        sessionId: "task-def",
424	+        workspaceId: "ws-1",
425	+        taskId: "task-2",
426	+        taskName: "T2",
427	+        title: "Task 2",
428	+      },
429	+    ];
430	+    const result = removeTaskTab(tabs, "task-def");
431	+    expect(result).toHaveLength(1);
432	+    expect(result[0]?.sessionId).toBe("task-abc");
433	+    // The remaining tab still has parentFeatureTabSessionId
434	+    expect(result[0]?.parentFeatureTabSessionId).toBe("feat-xyz");
435	+  });
436	+});
437	+
438	+// ─── Test: FeatureTasksPanel calls onOpenTaskTab ──────────────────────────────
439	+
440	+// Mock useDocumentContent
441	+vi.mock("../features/board/hooks/useDocumentContent", () => ({
