447	+}));
448	+
449	+// Mock status helpers
450	+vi.mock("../features/tasks/lib/status", () => ({
451	+  formatStatusLabel: vi.fn((s: string) => s),
452	+  getStatusStyle: vi.fn(() => ({ bg: "bg-gray-100", text: "text-gray-800" })),
453	+}));
454	+
455	+import { FeatureTasksPanel } from "../features/board/components/FeatureTabView/FeatureTasksPanel";
456	+
457	+function makeFeatureDetail(overrides: Partial<FeatureDetail> = {}): FeatureDetail {
458	+  return {
459	+    id: "feat-uuid-1",
460	+    feature_id: "feat-uuid-1",
461	+    feature_name: "my-feature",
462	+    title: "My Feature",
463	+    status: "in_implementation",
464	+    current_stage: "in_implementation",
465	+    task_counts: { total: 0, done: 0, in_progress: 0, blocked: 0, ready: 0, todo: 0 },
466	+    workspace_id: "ws-uuid-1",
467	+    documents: [],
468	+    tasks: [],
469	+    activity: [],
470	+    updated_at: "2026-01-01T00:00:00Z",
471	+    source_state: { stale: false },
472	+    ...overrides,
473	+  };
474	+}
475	+
476	+function makeTaskSummary(overrides: Partial<TaskSummary> = {}): TaskSummary {
477	+  return {
478	+    id: "task-uuid-1",
479	+    task_id: "task-uuid-1",
480	+    task_name: "T3",
481	+    feature_id: "feat-uuid-1",
482	+    feature_name: "my-feature",
483	+    title: "Implement kanban board",
484	+    status: "in_progress",
485	+    repo: "acme/ui",
