491	+  };
492	+}
493	+
494	+describe("FeatureTasksPanel — onOpenTaskTab callback", () => {
495	+  it("renders task rows and calls onOpenTaskTab with task details", () => {
496	+    const onOpenTaskTab = vi.fn();
497	+    const feature = makeFeatureDetail({
498	+      tasks: [makeTaskSummary({ task_name: "T3", title: "Implement kanban board" })],
499	+    });
500	+
501	+    const html = renderToStaticMarkup(
502	+      React.createElement(FeatureTasksPanel, {
503	+        feature,
